            AuthenticationHeaderValue authorization = request.Headers.Authorization;

            if (authorization == null)
                return Task.CompletedTask;
            if (authorization.Scheme != "Bearer")
                return Task.CompletedTask;
            if (String.IsNullOrEmpty(authorization.Parameter))
            {
                context.ErrorResult = new AuthenticationFailureResult("Missing token", request);
                return Task.CompletedTask;
            }
            var token = authorization.Parameter;
            var user = User.GetUserByToken(token);
            if (user == null)
            {
                context.ErrorResult = new AuthenticationFailureResult("Invalid token", request);
                return Task.CompletedTask;
            }
            if (user.TokenDateExpire < DateTime.Now)
            {
                context.ErrorResult = new AuthenticationFailureResult("Token expired", request);
                return Task.CompletedTask;
            }
            string role = user.IsAdmin == 1 ? "admin" : "user";
            var identity = new GenericIdentity(user.Email ?? "Anonymous Identity", "Bearer");
            identity.AddClaim(new Claim(ClaimTypes.NameIdentifier, user.id.ToString()));
            if (!string.IsNullOrWhiteSpace(user.Email))
                identity.AddClaim(new Claim(ClaimTypes.Email, user.Email));
            identity.AddClaim(new Claim("token", user.Token));
            context.Principal = new GenericPrincipal(identity, new string[] { role });
            return Task.CompletedTask;
